package com.analyzer.risk.model;

import jakarta.persistence.*;
import lombok.*;
import org.hibernate.annotations.CreationTimestamp;

import java.time.Instant;
import java.util.ArrayList;
import java.util.List;

/**
 * Relational JPA Entity mapping required to store synthesized safe patch code blocks
 * generated by the Multi-Agent Refactoring Negotiation Layer.
 */
@Entity
@Table(name = "refactor_proposals", indexes = {
    @Index(name = "idx_refactor_pr_id", columnList = "analysis_id"),
    @Index(name = "idx_refactor_applied", columnList = "isApplied")
})
@Getter
@Setter
@Builder
@NoArgsConstructor
@AllArgsConstructor
public class RefactorProposalEntity {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @OneToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "analysis_id", nullable = false)
    private PullRequestAnalysis analysis;

    @Column(nullable = false, length = 32)
    private String threatSeverity;

    @Column(columnDefinition = "TEXT", nullable = false)
    private String criticRationale;

    @Column(columnDefinition = "TEXT", nullable = false)
    private String originalBreakingSnippet;

    @Column(columnDefinition = "TEXT", nullable = false)
    private String refactoredCodeSnippet;

    @Column(nullable = false, length = 255)
    private String backwardCompatibilityStrategy;

    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "refactor_mitigated_services", joinColumns = @JoinColumn(name = "proposal_id"))
    @Column(name = "service_name")
    @Builder.Default
    private List<String> mitigatedBlastRadiusServices = new ArrayList<>();

    @Column(nullable = false)
    @Builder.Default
    private boolean isApplied = false;

    @CreationTimestamp
    @Column(nullable = false, updatable = false)
    private Instant negotiatedAt;

    private Instant appliedAt;
}
